<?php $unlinked=query('SELECT p.id,p.full_name FROM players p LEFT JOIN users u ON u.player_id=p.id WHERE p.is_active=1 AND u.id IS NULL ORDER BY p.full_name'); ?>
<section class="panel mb-4"><h2>Tạo tài khoản cầu thủ</h2>
<?php if($unlinked): ?><form method="post" class="form-grid"><?= csrf() ?><input type="hidden" name="action" value="create-user"><?php select_field('Cầu thủ','player_id',array_column($unlinked,'full_name','id'),''); field('Username','username','','text',true,'autocomplete="off" minlength="3" maxlength="60"'); field('Password','password','','password',true,'autocomplete="new-password" minlength="8" maxlength="72"'); ?><div class="align-self-end"><button class="btn btn-dark">Tạo tài khoản</button></div></form>
<?php else: ?><p class="muted mt-3">Không có cầu thủ Active chưa được cấp tài khoản.</p><?php endif; ?></section>
<section class="panel"><h2>Player accounts</h2><p class="muted">Khóa/mở tài khoản và đặt lại mật khẩu. Để trống mật khẩu nếu không cần thay đổi. Admin đổi mật khẩu tại My account.</p><?php foreach(query("SELECT u.id,u.username,u.is_active,p.full_name FROM users u JOIN players p ON p.id=u.player_id WHERE u.role='PLAYER' ORDER BY p.full_name") as $u): ?><form method="post" class="data-row"><?= csrf() ?><input type="hidden" name="action" value="save-user"><input type="hidden" name="id" value="<?= e($u['id']) ?>"><div class="data-player"><strong><?= e($u['full_name']) ?></strong><small><?= e($u['username']) ?></small></div><?php select_field('Account','is_active',['1'=>'Active','0'=>'Locked'],$u['is_active']); field('New password','password','','password',false,'autocomplete="new-password" minlength="8" maxlength="72"'); ?><button class="btn btn-dark">Save</button></form><?php endforeach; ?></section>
